// Upgrading REAL old-v3 databases (generated by the code of the commits that shipped
// them, see test/fixtures/db/*.json) to the current schema, then using them.
import 'dart:convert';
import 'dart:io';

import 'package:drift/native.dart';
import 'package:fils/core/ledger/ledger.dart';
import 'package:fils/core/parsing/models.dart';
import 'package:fils/data/db/database.dart';
import 'package:fils/data/ingestion.dart';
import 'package:fils/data/store.dart';
import 'package:flutter_test/flutter_test.dart';

const tables = ['accounts', 'transactions', 'source_events', 'categories', 'budgets', 'goals', 'outbox', 'audit_events', 'settings'];

Future<int> count(AppDatabase db, String t) async => (await db.customSelect('SELECT COUNT(*) AS n FROM $t').getSingle()).data['n'] as int;
Future<int> expense(AppDatabase db) async => (await db
        .customSelect("SELECT COALESCE(SUM(amount_minor),0) AS n FROM transactions WHERE deleted_at IS NULL AND kind='expense' AND status IN ('posted','pending')")
        .getSingle())
    .data['n'] as int;

void main() {
  for (final commit in ['15700e1', '5b7d6fc']) {
    test('old v3 from $commit → current: all records kept, columns added, ingestion and review resolution work', () async {
      final manifest = jsonDecode(File('test/fixtures/db/v3_$commit.db.json').readAsStringSync()) as Map<String, dynamic>;
      expect(manifest['user_version'], 3);
      expect((manifest['source_events_columns'] as List).contains('held_group'), isFalse, reason: 'fixture is a genuine pre-held_group v3 db');
      final dir = await Directory.systemTemp.createTemp('fils_v4');
      final f = File('${dir.path}/old.db');
      File('test/fixtures/db/v3_$commit.db').copySync(f.path);
      final t0 = DateTime.utc(2026, 11, 22, 15);
      var db = AppDatabase(NativeDatabase(f));
      final s = FinanceStore(db, clock: () => t0);

      // Upgrade happens on first open.
      expect((await db.customSelect('PRAGMA user_version').getSingle()).data.values.first, db.schemaVersion);
      expect(db.schemaVersion, greaterThan(3));
      final cols = (await db.customSelect("SELECT name FROM pragma_table_info('source_events')").get()).map((r) => r.data['name']).toSet();
      expect(cols, containsAll(['counter_last4', 'match_candidates', 'held_group']));
      final idx = await db.customSelect("SELECT sql FROM sqlite_master WHERE name='idx_src_platform'").getSingle();
      expect(idx.data['sql'] as String, contains('UNIQUE'));

      // Every record preserved.
      final counts = (manifest['counts'] as Map).cast<String, int>();
      for (final t in tables) {
        expect(await count(db, t), counts[t], reason: '$t rows preserved');
      }
      expect(await expense(db), manifest['expense_minor']);
      expect((await s.allTransactions()).length, counts['transactions']);

      // A capture held by the old build is still resolvable after the upgrade.
      final heldIds = (manifest['held_event_ids'] as List).cast<String>();
      final ing = IngestionService(s);
      for (final id in heldIds) {
        final before = await expense(db);
        final r = await ing.confirmSeparate(id);
        expect(r.outcome, IngestOutcome.posted);
        expect(await expense(db), before + 1500);
        expect((await ing.confirmSeparate(id)).message, 'already resolved');
      }

      // New ingestion: replay of an old platform id is a duplicate (unique index intact).
      final replay = await ing.ingest(RawEvent(text: 'Purchase of KWD 5.250 at TALABAT card ending 1234. Available balance KWD 994.750',
          receivedAt: DateTime.utc(2026, 11, 22, 11, 5), source: SourceKind.sms, sender: 'NBK', sourceId: 'p1'));
      expect(replay.outcome, IngestOutcome.duplicate);
      // A new held capture, a grouped re-delivery, and their resolution (uses held_group).
      final txBefore = (await s.allTransactions()).length;
      await ing.ingest(RawEvent(text: 'Authorization of KWD 12.000 at STARBUCKS on card ending 1234 is pending', receivedAt: t0, source: SourceKind.sms, sender: 'NBK', sourceId: 'p3'));
      const settle = 'Purchase of KWD 11.000 at STARBUCKS on card ending 1234';
      final h = await ing.ingest(RawEvent(text: settle, receivedAt: t0.add(const Duration(hours: 1)), source: SourceKind.sms, sender: 'NBK', sourceId: 'st'));
      expect(h.outcome, IngestOutcome.possibleDuplicate, reason: 'old pending 10.000 and new 12.000 both qualify');
      final tw = await ing.ingest(RawEvent(text: settle, receivedAt: t0.add(const Duration(hours: 1, seconds: 20)), source: SourceKind.notification, sender: 'NBK', sourceId: 'n'));
      expect(tw.outcome, IngestOutcome.possibleDuplicate);
      final group = (await (db.select(db.sourceEvents)..where((x) => x.id.equals(tw.sourceEventId))).getSingle()).heldGroup;
      expect(group, h.sourceEventId);
      final cand = (await (db.select(db.sourceEvents)..where((x) => x.id.equals(h.sourceEventId))).getSingle()).matchCandidates!.split(',');
      final r = await ing.confirmSameTransaction(h.sourceEventId, cand.first);
      expect(r.outcome, IngestOutcome.settledPending);
      expect((await (db.select(db.sourceEvents)..where((x) => x.id.equals(tw.sourceEventId))).getSingle()).status, 'merged');
      expect((await s.allTransactions()).length, txBefore + 1);
      expect((await s.transaction(cand.first))!.status, TxStatuses.posted);
      expect(await ing.dismissHeld(h.sourceEventId), isFalse);

      // Reopen: no second migration, nothing lost.
      final n = await count(db, 'transactions');
      await db.close();
      db = AppDatabase(NativeDatabase(f));
      expect(await count(db, 'transactions'), n);
      expect((await db.customSelect('PRAGMA user_version').getSingle()).data.values.first, db.schemaVersion);
      await db.close();
      await dir.delete(recursive: true);
    });
  }
}
